import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { svg } from './svg.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Base64 copies of the files in /fonts, generated by scripts/build-fonts.js.
// Cards embed them because an SVG shown as an image can't load external fonts.
const fontsBase64 = JSON.parse(fs.readFileSync(path.join(__dirname, '../assets/fontsBase64.json'), 'utf8'));

/** @font-face rules for the card fonts, to place inside a card's <style> element. */
export function fontFaces() {
  return svg`
        @font-face {
          font-family: 'Rajdhani';
          src: url('data:font/truetype;charset=utf-8;base64,${fontsBase64['Rajdhani-Regular']}') format('truetype');
        }
        @font-face {
          font-family: 'ChakraPetch';
          src: url('data:font/truetype;charset=utf-8;base64,${fontsBase64['ChakraPetch-Regular']}') format('truetype');
        }
        @font-face {
          font-family: 'LibreBarcode128';
          src: url('data:font/truetype;charset=utf-8;base64,${fontsBase64['LibreBarcode128-Regular']}') format('truetype');
        }`;
}
